import{z as n,x as B,o as E,c as A,q as i,j as e,D as t,d as s,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"分解着色冲突","description":"","frontmatter":{"title":"分解着色冲突","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/decomposition-coloring-conflict.md","filePath":"litho/decomposition-coloring-conflict.md","lastUpdated":1791413859000}'),p={name:"litho/decomposition-coloring-conflict.md"};function c(h,a,d,C,D,m){const o=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=i('<h1 id="分解着色冲突" tabindex="-1">分解着色冲突 <a class="header-anchor" href="#分解着色冲突" aria-label="Permalink to &quot;分解着色冲突&quot;">​</a></h1><div class="epigraph"><p>双重图形先是一张冲突图能不能染色；奇圈、stitch 和三色不足，不是 OPC 修边能消掉的红。</p><footer>—— 对照双重/多重图形着色、冲突图与 stitch 的公开算法传统；[LELE 颜色分解](/litho/lele-color-decomposition) 已钉过两次曝光</footer></div><p><a href="/litho/ml-hotspot-prediction">上一课</a>把学习模型限制在排序。缺口是分解：间距小于单次可印极限的边必须分到不同曝光（不同「色」），这是图论约束，不是风险分。<a href="/litho/lele-color-decomposition">LELE 颜色分解</a> 已写两次曝光的染色；本课把冲突收进签核门：LRC 必须能报无法着色，而不是留给掩模厂。设计规则为何长成现在这样，留给<a href="/litho/design-rule-origin">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次 EUV 或浸没仍覆盖不了的节距，用 LELE、LELELE、切线或多色金属。冲突图：多边形（或边段）为顶点，间距小于最小同色间距则连边。2-色可染当且仅当图是二分的；奇圈即冲突。三重曝光对应 3-色，成本跳一层掩模与套刻。SADP/SAQP 不是染色，芯轴与 spacer 的「颜色」是自对准的，冲突形态不同，本课不改写成 spacer 工艺。</p><p>缺口是<strong>签核时的冲突</strong>，不是重讲一遍 LELE 流程。布线器在合法 DRC 下仍可画出奇圈；LFD 若没把可染性当约束，热点预测再准也修不回一张不可分解的网。</p><p>「奇圈即冲突」到底长什么样？三块多边形两两挨得太近，冲突图就闭合成三角形：无论怎么把三块分成两组，总有一对冤家同组。四边形的圈却可以交替分色，安然无恙。</p>',7)),(E(),e(r,null,{default:t(()=>[l(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20TRI%5B%22%E4%B8%89%E5%9D%97%E4%BA%92%E8%BF%91%EF%BC%9A%E5%A5%87%E5%9C%88%22%5D%0A%20%20%20%20A%5B%22%E5%A4%9A%E8%BE%B9%E5%BD%A2%E7%94%B2%22%5D%20---%20B%5B%22%E5%A4%9A%E8%BE%B9%E5%BD%A2%E4%B9%99%22%5D%0A%20%20%20%20B%20---%20C%5B%22%E5%A4%9A%E8%BE%B9%E5%BD%A2%E4%B8%99%22%5D%0A%20%20%20%20C%20---%20A%0A%20%20end%0A%20%20subgraph%20CHAIN%5B%22%E5%9B%9B%E5%9D%97%E6%88%90%E9%93%BE%EF%BC%9A%E5%8F%AF%E4%BA%8C%E6%9F%93%22%5D%0A%20%20%20%20D%5B%22%E4%B8%81%22%5D%20---%20E%5B%22%E6%88%8A%22%5D%0A%20%20%20%20E%20---%20F%5B%22%E5%B7%B1%22%5D%0A%20%20%20%20F%20---%20G%5B%22%E5%BA%9A%22%5D%0A%20%20end%0A%20%20TRI%20--%3E%20X%5B%222%20%E8%89%B2%E5%BF%85%E6%9C%89%E4%B8%80%E5%AF%B9%E5%90%8C%E8%89%B2%EF%BC%8C%E7%A1%AC%E5%86%B2%E7%AA%81%22%5D%0A%20%20CHAIN%20--%3E%20Y%5B%22%E4%BA%A4%E6%9B%BF%E7%94%B2%E4%B9%99%E7%94%B2%E4%B9%99%EF%BC%8C%E5%90%88%E6%B3%95%E5%88%86%E8%A7%A3%22%5D%0A%20%20X%20--%3E%20OUT%5B%22%E6%94%B9%E6%8B%93%E6%89%91%20%2F%20stitch%20%2F%20%E5%8A%A0%E7%AC%AC%E4%B8%89%E8%89%B2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="stitch-是冲突的另一种债" tabindex="-1">stitch 是冲突的另一种债 <a class="header-anchor" href="#stitch-是冲突的另一种债" aria-label="Permalink to &quot;stitch 是冲突的另一种债&quot;">​</a></h3><p>同一根导线被拆到两色，接头（stitch）引入套刻敏感的接缝和局部 CD。允许 stitch 可以消灭部分奇圈，却把套刻预算写进导线可靠性。禁止 stitch 则更多设计必须改拓扑。合同要声明：本层是否允许 stitch、最小重叠、是否禁止在 via 落点。</p><p><span class="marginnote">着色冲突是硬失败：没有「OPC 再跑一晚」这回事。报告应指向圈上的边，而不是一串 EPE 纳米。</span></p><p><span class="marginnote">术语翻译：「冲突图染色」就是给每块多边形发一个颜色编号，颜色=第几次曝光；规则只有一条——挨得太近（间距小于同色下限）的不能同色。这与给地图相邻国家涂不同色是同一道数学题：涂不出来，就说明这张版图用两次曝光分不开。</span></p><p><span class="marginnote">直觉类比：奇圈像「三个人互相看不顺眼」——甲乙要分开、乙丙要分开、丙甲也要分开，可组只有两个，怎么分都有一对冤家坐同桌。四个人的圈反而好办：交替坐就能两两错开。冲突报告盯着那个「三人圈」，就是告诉布线器该拆哪条边。</span></p><p><span class="marginnote">常见误区：初学者容易以为布线器过了 DRC 就万事大吉。DRC 查的是单次曝光视角下的几何规则，可染性是另一条独立硬约束——一张全部合规的版图，仍可能围出一个三多边形奇圈，直接挡在磁带前，而且这不是 OPC 或更好的相机能救的，只能改拓扑、加 stitch 或多买一张掩模。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解工具：冲突图构建（含投影间距、jog、via 覆盖）、染色启发式、stitch 候选、合法化。签核：LRC 甲板含「未着色 / 同色间距 / stitch 规则」。与设计协同：轨道方向、via 网格、优选节距使图更易二分——这是 LFD 的分解侧。与 <a href="/litho/cut-mask-dpt">切线多重</a> 的关系：切线层有自己的冲突，不要和金属色混报。</p><p>换节点若从 LELE 改 EUV 单次，冲突图应整层删除，而不是留着旧色当装饰规则。</p><p>冲突报告要能回到版图坐标和圈上的边，供布线器或手工改拓扑。只报「本层冲突数」无法修。DPT 着色文献把 stitch 规则写成与最小同色间距并列的条款，LRC 甲板应同样并列，而不是藏在 OPC 日志里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小同色间距来自光学 + 套刻：两次曝光的相对位移把「不同色」的有效间距吃掉一截，所以着色规则比单次最小间隔更宽。奇圈无法 2-染是组合事实。工具用删除边（改设计）、加 stitch（改几何）、或加色（加掩模）三条路；三条都有成本函数，DTCO 已在上游选过哪条路允许。</p>',12)),(E(),e(r,null,{default:t(()=>[l(o,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E9%87%91%E5%B1%9E%20%2F%20%E5%88%87%E7%BA%BF%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20CG%5B%22%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A%20%20CG%20--%3E%20COL%5B%22k-%E6%9F%93%E8%89%B2%22%5D%0A%20%20COL%20--%3E%20OK%5B%22%E5%8F%AF%E5%88%86%E8%A7%A3%22%5D%0A%20%20COL%20--%3E%20ODD%5B%22%E5%A5%87%E5%9C%88%20%2F%20%E8%89%B2%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20ODD%20--%3E%20ST%5B%22stitch%20%E6%88%96%E6%94%B9%E8%AE%BE%E8%AE%A1%E6%88%96%E5%8A%A0%E8%89%B2%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>着色不保证可印：同色合法仍可能是光学热点。不把某分解器的「冲突为零」当硅上良率。不把图染色算法竞赛当光刻物理。</p><p>后课默认：不可着色是挡磁带的硬规则。下一课从这些硬规则回溯：设计手册里的数字从哪来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>着色冲突是冲突图可染性，OPC 修不掉奇圈。</li><li>stitch 用套刻债换可染性，必须进层合同。</li><li>LRC 要报圈与同色间距，而不是只报 EPE。</li><li>出处：DPT 着色与冲突图传统；LELE 分解公开论述。</li></ul>',5))])}const u=n(p,[["render",c]]);export{f as __pageData,u as default};
